import{_ as t,o,c as r,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Related inline creates — Production Readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Related inline creates — Production Readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/related-inline-creates-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Related inline creates — Production Readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/related-inline-creates-production-readiness"}]]},"headers":[],"relativePath":"deployment/related-inline-creates-production-readiness.md","filePath":"deployment/related-inline-creates-production-readiness.md","lastUpdated":1788612600000}'),n={name:"deployment/related-inline-creates-production-readiness.md"};function s(d,e,i,l,c,g){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="related-inline-creates-—-production-readiness" tabindex="-1">Related inline creates — Production Readiness <a class="header-anchor" href="#related-inline-creates-—-production-readiness" aria-label="Permalink to &quot;Related inline creates — Production Readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-04</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> after PR merge + migrate-first deploy + staging smoke</td></tr><tr><td><strong>Scope</strong></td><td>Platform-wide gated <strong>New</strong> dialogs on related FK pickers (Contact, Company, Opportunity, Lead, Vendor); URL query prefills preserved; catalog MINOR bumps</td></tr><tr><td><strong>Branch</strong></td><td><code>feature/related-inline-creates</code> (Frontend, Backend, Docs)</td></tr><tr><td><strong>Backend</strong></td><td>Idempotent catalog bump migration only (no new APIs)</td></tr><tr><td><strong>Frontend</strong></td><td>Shared <code>Create*Dialog</code> + <code>RelatedEntityPicker</code>; wired across CRM/billing/ops forms</td></tr><tr><td><strong>Docs</strong></td><td>Module Development Guide standard + user-guide notes + changelog + this audit</td></tr></tbody></table><p><strong>Companion docs:</strong> <a href="/developer-guide/module-development">Module development</a> · <a href="/changelog/">Changelog</a> · <a href="/deployment/upgrade">Upgrade</a></p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Create/edit forms that pick records from another module now offer a <strong>New</strong> control beside the picker. The dialog creates a minimal related record and auto-selects it so users do not leave the parent form. <strong>New</strong> is shown only when the related module is entitled <strong>and</strong> the user has <code>*.create</code>. Pickers require <code>hasModule</code> + <code>*.view</code>.</p><p>Platform freeze is intact: no AppLayout, auth, tenancy, RBAC, or billing redesign. Creates use existing tenant <code>*Service.create</code> endpoints; backend authz/policies are unchanged.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> — audit residuals <strong>B1/B2/M1/I2</strong> remediated; Mobile remains out of scope. Operator next: merge companion PRs, migrate catalog bumps, deploy Backend → Frontend → Docs, staging smoke.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Shared dialogs (company, contact, vendor, opportunity, lead)</td><td><strong>Pass</strong></td></tr><tr><td>RelatedEntityPicker + module/create gates</td><td><strong>Pass</strong></td></tr><tr><td>Wired forms (CRM, billing, purchasing, ops)</td><td><strong>Pass</strong></td></tr><tr><td>URL <code>?contact=</code> / <code>?company=</code> prefill survives form reset</td><td><strong>Pass</strong> (remediated)</td></tr><tr><td>Prefetch missing picker options for deep-link ids</td><td><strong>Pass</strong></td></tr><tr><td>Catalog MINOR bumps via idempotent migration</td><td><strong>Pass</strong></td></tr><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td>Playwright related-creates + invoices workflow + authz</td><td><strong>Pass</strong> (related-creates suite including authz)</td></tr><tr><td>Mobile SPA parity</td><td><strong>Out of scope</strong> (tenant web only)</td></tr><tr><td>Dedicated Pest</td><td><strong>N/A</strong> (no new backend endpoints)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>No new auth / tenancy / billing systems</td><td>Pass</td></tr><tr><td><strong>New</strong> gated by <code>hasModule(related)</code> + <code>related.create</code></td><td>Pass</td></tr><tr><td>Picker gated by <code>hasModule</code> + <code>related.view</code></td><td>Pass</td></tr><tr><td>Create calls existing tenant APIs (policy / form-request authz unchanged)</td><td>Pass</td></tr><tr><td>Dialogs are secondary UX only (not primary record pages)</td><td>Pass</td></tr></tbody></table><h3 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>B1</strong></td><td>High</td><td>URL prefill cleared when currency settings hydrate <code>reset()</code></td><td><strong>Remediated</strong> — reset keeps query params; prefill waits for module gates; merge prefetched contact/company into picker options</td></tr><tr><td><strong>B2</strong></td><td>Medium</td><td>Dialog submit raced empty controlled Name (Create stayed disabled)</td><td><strong>Remediated</strong> — shared Create*Dialogs reset fields on close (not open); e2e helper still asserts Name + enabled submit</td></tr><tr><td><strong>B3</strong></td><td>High</td><td>Dialog <strong>Create</strong> also submitted the parent create form (invoice/quotation/etc.) via React portal event bubbling</td><td><strong>Remediated</strong> — all shared Create*Dialog <code>onSubmit</code> call <code>stopPropagation</code></td></tr><tr><td><strong>M1</strong></td><td>Medium</td><td>User-guide create steps only detailed for invoices / quotations / POs</td><td><strong>Remediated</strong> — create steps updated for estimates, contracts, payments, credit notes, opportunities, projects, activities, help desk, documents, expenses, assets (plus existing invoices / quotations / POs / contacts)</td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>Shared-demo “module not installed” negative e2e invalid</td><td><strong>Removed</strong> — modules accumulate on demo tenant; Pest/module middleware remain source of truth</td></tr><tr><td><strong>I2</strong></td><td>Info</td><td><code>*.create</code> permission-only negative e2e not covered</td><td><strong>Remediated</strong> — Playwright <code>related-creates.authz</code> asserts Company/Contact pickers without <strong>New</strong> when <code>companies.create</code> / <code>contacts.create</code> are denied</td></tr><tr><td><strong>I3</strong></td><td>Info</td><td>EloSync-Mobile not updated</td><td><strong>Out of scope</strong> for this web UX</td></tr></tbody></table><p>No High, Medium, or Info <strong>open</strong> residuals for ship (Mobile remains out of scope).</p><hr><h2 id="change-inventory" tabindex="-1">Change inventory <a class="header-anchor" href="#change-inventory" aria-label="Permalink to &quot;Change inventory&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Migration <code>2026_09_03_204444_bump_modules_for_related_inline_creates</code> — MINOR bumps: invoices <strong>1.9.0</strong>, quotations <strong>1.7.0</strong>, estimates <strong>1.6.0</strong>, contracts <strong>1.3.0</strong>, payments <strong>1.3.0</strong>, credit-notes <strong>1.3.0</strong>, purchase-orders <strong>1.3.0</strong>, opportunities <strong>1.2.0</strong>, projects <strong>1.2.0</strong>, activities <strong>1.1.0</strong>, help-desk <strong>1.8.0</strong>, documents <strong>1.4.0</strong>, expenses <strong>1.4.0</strong>, assets <strong>1.1.0</strong>.</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li>Shared: <code>CreateCompanyDialog</code>, <code>CreateContactDialog</code>, <code>CreateVendorDialog</code>, <code>CreateOpportunityDialog</code>, <code>CreateLeadDialog</code>, <code>RelatedEntityPicker</code>.</li><li>Forms: contact, opportunity, quotation, contract, estimate, invoice, payment, credit note, project, activity, help desk, documents, purchase order, expense, asset.</li><li>Prefill: <code>withPrefillOption</code> + create-mode reset preserves <code>?contact=</code> / <code>?company=</code>.</li><li>Playwright: <code>related-creates/related-inline-creates</code> (shared session), <code>related-creates.authz</code> (create permission gate), module <code>*.related-creates</code>, contacts regression.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Module Development Guide related-create standard.</li><li>User-guide create notes (invoices, quotations, purchase orders) + overview version lines.</li><li>Changelog delivery note.</li><li>This production readiness page.</li></ul><hr><h2 id="deploy-sequence-migrate-first" tabindex="-1">Deploy sequence (migrate-first) <a class="header-anchor" href="#deploy-sequence-migrate-first" aria-label="Permalink to &quot;Deploy sequence (migrate-first)&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong> → <code>php artisan migrate --force</code> (catalog bumps only; idempotent).</li><li>Deploy <strong>Frontend</strong> SPA build.</li><li>Deploy <strong>Docs</strong>.</li><li>Staging smoke (below).</li><li>Production same order.</li></ol><p>No <code>db:seed</code> in production. Catalog bumps do <strong>not</strong> auto-install modules for workspaces that never entitled them.</p><hr><h2 id="staging-smoke-minimum" tabindex="-1">Staging smoke (minimum) <a class="header-anchor" href="#staging-smoke-minimum" aria-label="Permalink to &quot;Staging smoke (minimum)&quot;">​</a></h2><ol><li>Workspace with Contacts + Companies + Invoices: <strong>New invoice</strong> → <strong>New</strong> company → <strong>New</strong> contact → empty submit shows validation → fill line → Create → record appears with links.</li><li>Opportunities + Quotations: <strong>New quotation</strong> → empty submit shows “Opportunity is required” → <strong>New</strong> opportunity → Create quotation succeeds.</li><li>Vendors + Purchase Orders: <strong>New PO</strong> → empty submit shows “Vendor is required” → <strong>New</strong> vendor → Create succeeds.</li><li>Without Companies entitled (fresh workspace or uninstall if available): invoice form has no Company picker / <strong>New</strong>.</li><li>Contact view <strong>New quotation</strong> deep link still prefills Contact combobox after SPA load.</li><li>Role with <code>companies.view</code> / <code>contacts.view</code> but <strong>without</strong> create: invoice form shows Company/Contact pickers and <strong>no</strong> <strong>New</strong> buttons.</li></ol><hr><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><ul><li>Revert Frontend SPA first (dialogs disappear; pickers remain).</li><li>Catalog versions can remain elevated (cosmetic Marketplace version); optional down-migration only for local.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/changelog/">Changelog</a></li><li><a href="/developer-guide/module-development">Module development guide</a></li><li><a href="/user-guide/invoices">Invoices user guide</a></li><li><a href="/user-guide/quotations">Quotations user guide</a></li><li><a href="/user-guide/purchase-orders">Purchase orders user guide</a></li></ul>',35)])])}const p=t(n,[["render",s]]);export{m as __pageData,p as default};
